package java.util;
public class BitSet implements Cloneable,java.io.Serializable {private long[] words;public BitSet(){words=new long[1];}public BitSet(int nbits){if(nbits<0)throw new NegativeArraySizeException();words=new long[(nbits+63)>>>6];}private void check(int i){if(i<0)throw new IndexOutOfBoundsException();}private void range(int a,int b){check(a);if(b<a)throw new IndexOutOfBoundsException();}private void ensure(int i){int n=(i>>>6)+1;if(n>words.length){long[] w=new long[Math.max(n,words.length*2)];System.arraycopy(words,0,w,0,words.length);words=w;}}public void set(int i){check(i);ensure(i);words[i>>>6]|=1L<<i;}public void set(int i,boolean v){if(v)set(i);else clear(i);}public void set(int a,int b){range(a,b);for(int i=a;i<b;i++)set(i);}public void set(int a,int b,boolean v){if(v)set(a,b);else clear(a,b);}public void clear(int i){check(i);if((i>>>6)<words.length)words[i>>>6]&=~(1L<<i);}public void clear(int a,int b){range(a,b);for(int i=a;i<b&&i<size();i++)clear(i);}public void clear(){for(int i=0;i<words.length;i++)words[i]=0;}public void flip(int i){check(i);ensure(i);words[i>>>6]^=1L<<i;}public void flip(int a,int b){range(a,b);for(int i=a;i<b;i++)flip(i);}public boolean get(int i){check(i);return (i>>>6)<words.length&&(words[i>>>6]&(1L<<i))!=0;}public BitSet get(int a,int b){range(a,b);BitSet r=new BitSet(b-a);for(int i=a;i<b&&i<length();i++)if(get(i))r.set(i-a);return r;}public int nextSetBit(int from){check(from);for(int i=from;i<length();i++)if(get(i))return i;return -1;}public int nextClearBit(int from){check(from);int i=from;while(get(i))i++;return i;}public int previousSetBit(int from){if(from< -1)throw new IndexOutOfBoundsException();for(int i=Math.min(from,length()-1);i>=0;i--)if(get(i))return i;return -1;}public int previousClearBit(int from){if(from< -1)throw new IndexOutOfBoundsException();for(int i=from;i>=0;i--)if(!get(i))return i;return -1;}public int length(){for(int i=words.length-1;i>=0;i--)if(words[i]!=0){long x=words[i];int n=0;while(x!=0){x>>>=1;n++;}return i*64+n;}return 0;}public boolean isEmpty(){return length()==0;}public int size(){return words.length*64;}public int cardinality(){int n=0;for(long x:words)while(x!=0){x&=x-1;n++;}return n;}public boolean intersects(BitSet b){for(int i=0;i<Math.min(words.length,b.words.length);i++)if((words[i]&b.words[i])!=0)return true;return false;}public void and(BitSet b){for(int i=0;i<words.length;i++)words[i]&=i<b.words.length?b.words[i]:0;}public void or(BitSet b){if(b.length()>0)ensure(b.length()-1);for(int i=0;i<b.words.length&&i<words.length;i++)words[i]|=b.words[i];}public void xor(BitSet b){if(b.length()>0)ensure(b.length()-1);for(int i=0;i<b.words.length&&i<words.length;i++)words[i]^=b.words[i];}public void andNot(BitSet b){for(int i=0;i<Math.min(words.length,b.words.length);i++)words[i]&=~b.words[i];}public long[] toLongArray(){int n=(length()+63)>>>6;long[] a=new long[n];System.arraycopy(words,0,a,0,n);return a;}public byte[] toByteArray(){int n=(length()+7)>>>3;byte[] a=new byte[n];for(int i=0;i<n;i++)a[i]=(byte)(words[i>>>3]>>>((i&7)*8));return a;}public static BitSet valueOf(long[] a){BitSet b=new BitSet(a.length*64);System.arraycopy(a,0,b.words,0,a.length);return b;}public static BitSet valueOf(byte[] a){BitSet b=new BitSet(a.length*8);for(int i=0;i<a.length;i++)b.words[i>>>3]|=(long)(a[i]&255)<<((i&7)*8);return b;}public Object clone(){return valueOf(toLongArray());}public boolean equals(Object o){if(!(o instanceof BitSet))return false;BitSet b=(BitSet)o;int n=Math.max(words.length,b.words.length);for(int i=0;i<n;i++)if((i<words.length?words[i]:0)!=(i<b.words.length?b.words[i]:0))return false;return true;}public int hashCode(){long h=1234;for(int i=words.length;--i>=0;)h^=words[i]*(i+1);return (int)((h>>>32)^h);}public String toString(){StringBuilder s=new StringBuilder("{");boolean first=true;for(int i=nextSetBit(0);i>=0;i=nextSetBit(i+1)){if(!first)s.append(", ");s.append(i);first=false;}return s.append('}').toString();}}
